// Text-and-photo pairs: what the title says against what the photo shows. `expected` is the
// target system's outcome (plan 40, § 2 bis): a restricted word in the title sends the photos to a
// targeted question, and the photo decides.
const P = (title, pick, expected, why) => ({ title, pick, expected, why });
const PAIR_SPECS = [
  P('Robe blanc ivoire', { kind: 'ivory_dress' }, 'approve', 'colour word, no ivory on the photo'),
  P('Statuette en ivoire', { label: 'positive', group: 'ivory', kind: 'ivory_carving' }, 'refuse', 'the title and the photo agree: ivory'),
  P('Réplique de lampe Tiffany', { kind: 'lamp' }, 'approve', 'a replica lamp is allowed'),
  P('Sac de luxe, réplique', { kind: 'branded_bag' }, 'refuse', '« réplique » plus a luxury brand on the photo is a counterfeit'),
  P('Pistolet jouet pour enfant', { kind: 'toy_gun' }, 'approve', '« pistolet » names a toy'),
  P('Réplique airsoft', { kind: 'airsoft' }, 'approve', 'an airsoft replica is not a firearm and names no brand'),
  P('Objet décoratif', { label: 'positive', group: 'weapons', kind: 'firearm' }, 'refuse', 'no restricted word, the photo shows a firearm'),
  P('Bibelot ancien', { label: 'positive', group: 'protected_species', kind: 'taxidermy' }, 'refuse', 'no restricted word, the photo shows taxidermy'),
  P('Crâne en résine, décoration', { kind: 'skull_decoration' }, 'approve', 'decorative skull'),
  P('Crâne de collection', { label: 'positive', group: 'human_remains', kind: 'human_skull' }, 'refuse', 'no restricted word, the photo shows a human skull'),
  P('Casque militaire 14-18', { kind: 'militaria' }, 'approve', 'militaria without a Nazi symbol'),
  P('Insigne militaire allemand', { label: 'positive', group: 'nazi', kind: 'nazi_decoration' }, 'refuse', 'no restricted word, the photo shows a Nazi decoration'),
  P('Lot de monnaies trouvées au détecteur', { label: 'positive', group: 'cultural_goods', kind: 'detector_find' }, 'refuse', 'the title and the photo agree: a detector find'),
  P('Manteau en fausse fourrure de léopard', { kind: 'faux_fur' }, 'approve', '« fourrure de léopard » inside « fausse fourrure »'),
  P('Lunettes écaille de tortue', { kind: 'synthetic_tortoiseshell' }, 'approve', 'tortoiseshell pattern on acetate frames'),
  P('Livre archéologique illustré', { kind: 'archaeology_book' }, 'approve', 'a book about archaeology'),
  P('Peinture blanc ivoire', { kind: 'ivory_colour' }, 'approve', 'colour word, no ivory on the photo'),
  P('Animal naturalisé', { label: 'positive', group: 'protected_species', kind: 'taxidermy' }, 'refuse', 'the title and the photo agree: taxidermy'),
];

const ext = (url) => { const e = path.extname(new URL(url).pathname).toLowerCase(); return ['.jpg', '.jpeg', '.png', '.webp'].includes(e) ? e : '.jpg'; };
const fileOf = (label, id, url) => `vision/${label}/${id}${ext(url)}`;
const claimed = new Set();
const report = [];

/** Downloads `candidates` in order until `take` are pinned; returns the entries. */
async function pin(candidates, take, toEntry) {
  const out = [];
  for (let i = 0; i < candidates.length && out.length < take;) {
    const batch = candidates.slice(i, i + take - out.length);
    i += batch.length;
    const got = await pool(batch, MAX_PARALLEL, async (c) => {
      const e = toEntry(c);
      try { const { sha256 } = await download(e.url, path.join(ARTIFACTS, e.file)); return { ...e, sha256 }; } catch (err) { report.push(`download failed ${e.page || e.url}: ${err.message}`); return null; }
    });
    out.push(...got.filter(Boolean));
  }
  return out;
}

async function fromCommons(src) {
  const titles = src.source.startsWith('search:') ? await searchFileTitles(src.source.slice(7), MAX_TITLES) : await categoryFileTitles(src.source, MAX_TITLES);
  const order = seededOrder(titles, `${src.label}:${src.source}`);
  const usable = [];
  let skipped = 0;
  // imageinfo in seeded order, 50 at a time, until there is a margin for failed downloads.
  for (let i = 0; i < order.length && usable.length < src.take + 3; i += 50) {
    for (const f of await imageInfos(order.slice(i, i + 50))) {
      if (claimed.has(f.pageid) || unusable(f) || excluded(src, f.title)) { skipped++; continue; }
      usable.push(f);
    }
  }
  usable.sort((a, b) => order.indexOf(a.title) - order.indexOf(b.title));
  const where = src.source.startsWith('search:') ? `Commons search « ${src.source.slice(7)} »` : `Commons category « ${src.source} »`;
  const entries = await pin(usable, src.take, (f) => ({
    id: `wm-${f.pageid}`, label: src.label, group: src.group, kind: src.kind, url: f.url, page: f.page, license: f.license,
    licenseUrl: f.licenseUrl, author: f.author, sourceSha1: f.sourceSha1, file: fileOf(src.label, `wm-${f.pageid}`, f.url),
    note: src.note ? `${where}; ${src.note}` : where, ...(f.restrictions ? { restrictions: f.restrictions } : {}),
  }));
  for (const e of entries) claimed.add(Number(e.id.slice(3)));
  if (entries.length < src.take) report.push(`short: ${src.label}/${src.kind} « ${src.source} » ${entries.length}/${src.take} (${titles.length} files, ${skipped} skipped: licence, type, size, title or already used)`);
  console.log(`${src.label.padEnd(13)} ${String(src.group || '').padEnd(17)} ${String(entries.length).padStart(3)}/${src.take}  ${src.source}`);
  return entries;
}

/**
 * The demo library's photos (Wikimedia Commons files listed in the Dlala repository's
 * scripts/demo/preview/photos.json, reviewed for the marketplace preview): ordinary objects in real settings.
 * That list is not part of this repository: without it (DEMO_PHOTOS unset or missing), the `demo:` entries
 * already in vision-manifest.json are kept as they are.
 */
async function fromDemo() {
  const demoFile = process.env.DEMO_PHOTOS;
  if (!demoFile || !fs.existsSync(demoFile)) {
    const kept = fs.existsSync(MANIFEST) ? readJson(MANIFEST).images.filter((e) => String(e.kind).startsWith('demo:') && !claimed.has(Number(e.id.slice(3)))) : [];
    for (const e of kept) claimed.add(Number(e.id.slice(3)));
    console.log(`ordinary      demo              ${kept.length} kept from vision-manifest.json (set DEMO_PHOTOS to rebuild them)`);
    return kept;
  }
  const demo = readJson(demoFile);
  const types = new Map(demo.map((d) => [d.title, d.type]));
  // A margin of 10 % over DEMO_TAKE for files gone or unusable since the demo list was made.
  const drawn = seededOrder(demo.map((d) => d.title), 'demo').slice(0, Math.ceil(DEMO_TAKE * 1.1));
  const order = new Map(drawn.map((t, i) => [t, i]));
  const infos = (await imageInfos(drawn)).filter((f) => !claimed.has(f.pageid) && !unusable(f));
  infos.sort((a, b) => (order.get(a.title) ?? drawn.length) - (order.get(b.title) ?? drawn.length)); // a renamed file sorts last
  const entries = await pin(infos, DEMO_TAKE, (f) => ({
    id: `wm-${f.pageid}`, label: 'ordinary', group: null, kind: `demo:${types.get(f.title)}`, url: f.url, page: f.page, license: f.license,
    licenseUrl: f.licenseUrl, author: f.author, sourceSha1: f.sourceSha1, file: fileOf('ordinary', `wm-${f.pageid}`, f.url),
    note: 'demo library (scripts/demo/preview/photos.json): an ordinary object photographed in a real setting',
  }));
  for (const e of entries) claimed.add(Number(e.id.slice(3)));
  console.log(`ordinary      demo              ${entries.length}/${DEMO_TAKE} (of ${demo.length})`);
  return entries;
}

/** 1 000 ABO catalogue photos, from the same seeded order as the fingerprint set (disjoint by construction). */
async function fromAbo() {
  const { sha256: metaSha, rows } = await aboMetadata();
  const { ordinary } = aboDraws(rows);
  const entries = await pin(ordinary, ordinary.length, (r) => ({
    id: aboId(r), label: 'ordinary', group: null, kind: 'abo_catalogue', url: smallUrl(r.path), page: ABO_PAGE, license: ABO_LICENSE,
    licenseUrl: 'https://creativecommons.org/licenses/by/4.0/', author: ABO_AUTHOR, file: `vision/ordinary/${aboId(r)}.jpg`,
    note: `ABO small image (largest side 256 px), metadata sha256 ${metaSha.slice(0, 12)}…`,
  }));
  console.log(`ordinary      abo               ${entries.length}/${ordinary.length}`);
  return entries;
}

const entries = [];
// Wikimedia throttles anonymous clients hard: a category it keeps refusing is skipped and reported,
// so one run still writes what it has; the next run fills the gaps from the cache.
for (const src of SOURCES) {
  try { entries.push(...await fromCommons(src)); }
  catch (err) { report.push(`skipped (retry later): ${src.source} - ${String(err.message).slice(0, 80)}`); console.warn(`skipped ${src.source}`); }
}
entries.push(...await fromDemo());
entries.push(...await fromAbo());
const previous = fs.existsSync(MANIFEST) ? readJson(MANIFEST).images.filter((e) => e.label === 'injection') : [];
const ids = new Set(entries.map((e) => e.id));
const kept = previous.filter((e) => ids.has(e.parent));
if (kept.length < previous.length) report.push(`${previous.length - kept.length} injection entries dropped: their parent left the set; run make-injection.mjs`);
entries.push(...kept);

const LABELS = ['positive', 'hard_negative', 'ordinary', 'privacy', 'privacy_trap', 'injection'];
const counts = {};
for (const e of entries) { const k = e.group && e.label !== 'injection' ? `${e.label}:${e.group}` : e.label; counts[k] = (counts[k] || 0) + 1; }
writeJsonLines(MANIFEST, {
  about: 'Vision set (plan 40, phase 1). Labels by construction: Commons category, ABO, demo library, or a scripted injection. Files: <artifacts>/<file>. Licences as the source states them; attribution in `author`.',
  seed: SEED, thumbWidth: THUMB_WIDTH, labels: LABELS, counts: Object.fromEntries(Object.entries(counts).sort()),
}, 'images', entries);

// Pairs: the first unused image (manifest order) that matches each spec.
const used = new Set();
const pairs = PAIR_SPECS.map((p, i) => {
  const hit = entries.find((e) => !used.has(e.id) && e.label !== 'injection' && Object.entries(p.pick).every(([k, v]) => e[k] === v));
  if (!hit) { report.push(`pair without image: ${p.title}`); return null; }
  used.add(hit.id);
  return { id: `pair-${String(i + 1).padStart(2, '0')}`, title: p.title, images: [hit.id], expected: p.expected, group: hit.group, why: p.why };
}).filter(Boolean);
fs.writeFileSync(PAIRS, `${JSON.stringify({ about: 'Title-and-photo pairs (plan 40, phase 1): `expected` is the outcome the photo checks must reach; image ids refer to vision-manifest.json.', pairs }, null, 2)}\n`);

console.log(`\nvision-manifest.json: ${entries.length} images`, counts);
console.log(`pairs.json: ${pairs.length} pairs`);
if (report.length) console.log(`\n${report.join('\n')}`);
